// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/mishandled.sol";

contract MaliciousReceiver {
    // Deny all payments by permanently reverting in the receive function
    // Ensures any .send() or .transfer() call to this contract fails
    receive() external payable {
        revert("MaliciousReceiver rejects payments");
    }
}

contract SendBackTest is Test {
    SendBack public sendBack;
    MaliciousReceiver public maliciousReceiver;

    function setUp() public {
        sendBack = new SendBack();
        maliciousReceiver = new MaliciousReceiver();
    }

    function test_MissingReturnValueCheck() public {
        // Fund the malicious receiver contract with 1 ether
        vm.deal(address(maliciousReceiver), 1 ether);

        // MaliciousReceiver deposits 1 ether to create a balance
        vm.prank(address(maliciousReceiver));
        sendBack.deposit{value: 1 ether}();

        // Pre-withdrawal state checks
        uint256 preWithdrawUserBalance = sendBack.userBalances(address(maliciousReceiver));
        uint256 preWithdrawContractBalance = address(sendBack).balance;
        uint256 preWithdrawContractReportedBalance = sendBack.getContractBalance();

        // 1. Verify deposit was successful
        assertEq(preWithdrawUserBalance, 1 ether, "User balance should be 1 ether after deposit");
        assertEq(preWithdrawContractBalance, 1 ether, "Contract ETH balance should be 1 ether after deposit");
        assertEq(preWithdrawContractReportedBalance, 1 ether, "getContractBalance() should return 1 ether");

        // Attempt withdrawal from malicious contract (will fail)
        vm.prank(address(maliciousReceiver));
        sendBack.withdrawBalance();  // Returns false, but doesn't revert!

        // Post-withdrawal state checks
        uint256 postWithdrawUserBalance = sendBack.userBalances(address(maliciousReceiver));
        uint256 postWithdrawContractBalance = address(sendBack).balance;
        uint256 postWithdrawContractReportedBalance = sendBack.getContractBalance();

        // 2. Validate the vulnerability:
        // - User balance was incorrectly reset to 0 despite failed transfer
        // - ETH remains in contract (both actual and reported balances unchanged)
        // - The user has lost funds due to state change without successful transfer
        assertEq(postWithdrawUserBalance, 0, "User balance was incorrectly reset to 0 after failed transfer");
        assertEq(postWithdrawContractBalance, 1 ether, "Contract ETH balance should remain 1 ether after failed withdrawal");
        assertEq(postWithdrawContractReportedBalance, 1 ether, "getContractBalance() should still show 1 ether after failed withdrawal");
        assertEq(address(maliciousReceiver).balance, 0, "MaliciousReceiver should not have received any ETH");
    }
}
